def _hash_html_spans(self, text):
    # Used for safe_mode.

    def _is_auto_link(s):
        if ':' in s and self._auto_link_re.match(s):
            return True
        elif '@' in s and self._auto_email_link_re.match(s):
            return True
        return False

    tokens = []
