func isLoopbackURI(requested *url.URL, registeredURI string) bool {
	registered, err := url.Parse(registeredURI)
	if err != nil {
		return false
	}

	if registered.Scheme != "http" || !isLoopbackAddress(registered.Host) {
		return false
	}

	if requested.Scheme == "http" && isLoopbackAddress(requested.Host) && registered.Path == requested.Path {
		return true
	}

	return false
}

func isMatchingRedirectURI(uri string, haystack []string) bool {
	requested, err := url.Parse(uri)
	if err != nil {
		return false
	}

	for _, b := range haystack {
		if strings.ToLower(b) == strings.ToLower(uri) || isLoopbackURI(requested, b) {
			return true
		}
	}
	return false
}

public function process(NodeInterface $node, $interceptorPosition, ParsingState $parsingState)
{
    if ($interceptorPosition === InterceptorInterface::INTERCEPT_OPENING_VIEWHELPER) {
        if (!$node->getUninitializedViewHelper()->isChildrenEscapingEnabled()) {
            $this->childrenEscapingEnabled = false;
            $this->viewHelperNodesWhichDisableTheInterceptor[] = $node;
        }
    } elseif ($interceptorPosition === InterceptorInterface::INTERCEPT_CLOSING_VIEWHELPER) {
        if (end($this->viewHelperNodesWhichDisableTheInterceptor) === $node) {
            array_pop($this->viewHelperNodesWhichDisableTheInterceptor);
            if (count($this->viewHelperNodesWhichDisableTheInterceptor) === 0) {
                $this->childrenEscapingEnabled = true;
            }
        }
        if ($this->childrenEscapingEnabled && $node->getUninitializedViewHelper()->isOutputEscapingEnabled()) {
            $node = new EscapingNode($node);
        }
    } elseif ($this->childrenEscapingEnabled && $node instanceof ObjectAccessorNode) {
        $node = new EscapingNode($node);
    }
    return $node;
}

private function wash_uri($uri, $blocked_source = false, $is_image = true)
{
    if (!empty($this->config['cid_map'][$uri])) {
        return $this->config['cid_map'][$uri];
    }

    $key = $this->config['base_url'] . $uri;
    if (!empty($this->config['cid_map'][$key])) {
        return $this->config['cid_map'][$key];
    }

    // allow url(#id) used in SVG
    if (isset($uri[0]) && $uri[0] == '#') {
        if ($this->_css_prefix !== null) {
            $uri = '#' . $this->_css_prefix . substr($uri, 1);
        }

        return $uri;
    }

    if (preg_match('/^(http|https|ftp):.+/i', $uri)) {
        if (!empty($this->config['allow_remote'])) {
            return $uri;
        }

        $this->extlinks = true;
        if ($is_image && !empty($this->config['blocked_src'])) {
            return $this->config['blocked_src'];
        }
    }
    else if ($is_image && preg_match('/^data:image.+/i', $uri)) { // RFC2397
        return $uri;
    }
}

