        );
        // Allow  tag
        //$config->set('HTML.Doctype', 'HTML 4.01 Transitional');
        $config->set('HTML.SafeIframe', true);
        $purifier[$user_status] = new HTMLPurifier($config);
    }

    if (is_array($var)) {
        return $purifier[$user_status]->purifyArray($var);
