static wrapPlainText(text: string, options?: any) {
  if(emojiSupported) {
    return text;
  }

  if(!text || !text.length) {
    return '';
  }

  options = options || {};

  text = text.replace(/\ufe0f/g, '');

  let match: RegExpMatchArray;
  let raw = text;
  let html: string[] = [],
      emojiTitle: string,
      emojiCode: string;

  while((match = raw.match(fullRegExp))) {
    html.push(raw.substr(0, match.index));

    if(match[8]) {
      if((emojiCode = emojiMap[match[8]]) &&
        (emojiTitle = emojiData[emojiCode][1][0])) {
        html.push(':' + emojiTitle + ':');
      } else {
        html.push(match[0]);
      }
    } else {
      html.push(match[0]);
    }

    raw = raw.substr(match.index + match[0].length);
  }

  html.push(raw);

  return html.join('');
}

