const escapeFunction = (string) => {
  let escaped = "";
  let start = 0;
  let end = 0;

  do {
    const escapedCharacter = escapeDictionary[string[end++]];
    if (escapedCharacter) {
      escaped += string.slice(start, end - 1) + escapedCharacter;
      start = end;
    }
  } while (end < string.length);

  return escaped + string.slice(start, end);
};

