            case '\t' -> lastIndex = flushAndEscape(value, lastIndex, i, "\\t", output);
            case '<' -> lastIndex = flushAndEscape(value, lastIndex, i, "\\u003C", output);
            case '>' -> lastIndex = flushAndEscape(value, lastIndex, i, "\\u003E", output);
