public static function cleanseConfig(array $config): array
{
    foreach ($config as $key => $value) {
        if (is_string($key) && (str_starts_with($key, 'on ') || str_starts_with($key, 'as '))) {
            unset($config[$key]);
            continue;
        }
        if (is_array($value)) {
            $config[$key] = static::cleanseConfig($value);
        }
    }
    return $config;
}

private static function attribute_value($node, $attr_name, $attr_value)
{
    $attr_name = strtolower($attr_name);

    foreach ($node->attributes as $name => $attr) {
        if (strtolower($name) === $attr_name) {
            if (strtolower($attr_value) === strtolower(trim($attr->nodeValue))) {
                return true;
            }
        }
    }

    return false;
}

